\section{कमकुवत उपायांच्या अस्तित्वासाठी आणि अद्वितीयतेसाठी सिद्धतेची रूपरेषा}

आपण गुळगुळीत सीमारेषा असलेल्या मर्यादित डोमेन $\Omega\subset\mathbb{R}^n$ वरील रेषीय लंबवर्तुळाकार ऑपरेटरसाठी सीमारेषा मूल्य समस्येचा विचार करतो:
\begin{equation}\label{eq:elliptic}
 -\Delta u + c u = f \quad\text{in }\Omega.
\end{equation}
येथे $c\in L^\infty(\Omega)$ जवळजवळ सर्वत्र $c(x)\ge c_0>0$ चे समाधान करते, आणि $f\in L^2(\Omega)$. कमकुवत सूत्र खालीलप्रमाणे आहे: असे $u\in H^1_0(\Omega)$ शोधा की
\[
a(u,v)=\int_\Omega (\nabla u\cdot\nabla v + c\,u v)\,dx = \int_\Omega f v\,dx,\qquad\forall v\in H^1_0(\Omega).
\]

\begin{theorem}[कमकुवत उपायांची अद्वितीयता]\label{thm:uniqueness}
जर $u\in H^1_0(\Omega)$ हे $f\equiv 0$ सह कमकुवत अर्थाने \eqref{eq:elliptic} चे समाधान करत असेल, तर $u\equiv 0$ असते.
\end{theorem}

\begin{proof}
प्रमाणित ऊर्जा पद्धत लागू होते. समजा $u$ हे एकजिनसी कमकुवत समस्येचे समाधान करते आणि $v=u$ सह चाचणी केली जाते. सक्तीचा वापर करून आपल्याला मिळते
\begin{equation}\label{eq:coercive}
a(u,u)=\int_\Omega |\nabla u|^2 + c|u|^2\,dx \ge \min(1,c_0)\|u\|_{H^1_0(\Omega)}^2.
\end{equation}
उजवी बाजू शून्य असल्याने, \eqref{eq:coercive} हे जवळजवळ सर्वत्र $u=0$ दर्शवते. यामुळे अद्वितीयतेचा युक्तिवाद पूर्ण होतो.
\end{proof}

